mapper.sql:
NOT EXISTS (
    SELECT 1 FROM sys_notifications_receiver r
    WHERE r.notification_id = n.id AND r.user_id = #{userId}
      AND (r.send_code = n.send_code OR r.send_code IS NULL)
      AND r.is_read = 1 AND r.is_deleted = 0
)

NOT EXISTS (
    SELECT 1 FROM sys_notifications_receiver r
    WHERE r.notification_id = n.id AND r.user_id = #{userId}
      AND (r.send_code = n.send_code OR r.send_code IS NULL)
      AND r.is_deleted = 1
)

mapper.select:
select n.id, n.from_user_id, n.business_id, n.business_type, n.title, n.message, n.link, n.create_time, u.nickname as to_nickname, u1.nickname as from_nickname, COALESCE(e.title, '') as business_title, CASE WHEN EXISTS ( SELECT 1 FROM sys_notifications_receiver r WHERE r.notification_id = n.id AND r.user_id = #{userId} AND (r.send_code = n.send_code OR r.send_code IS NULL) AND r.is_read = 1 AND r.is_deleted = 0 ) THEN 1 ELSE 0 END AS is_read from sys_notifications n left join sys_user u on u.id = left join sys_user u1 on n.from_user_id = u1.id left join sys_notice e on n.business_id = e.id and n.business_type = 'notice'
n.del_flag = 0 and and
and n.business_type = #{notifications.businessType}
and n.business_type IN
#{item}
order by is_read asc, n.create_time desc

select n.id, n.from_user_id, n.business_id, n.business_type, n.title, n.message, n.link, n.notice_push, (select count(1) from sys_notifications_receiver r where r.notification_id = n.id and (r.send_code = n.send_code or r.send_code is null)) as read_count, n.del_flag, n.create_time, u1.nickname as from_nickname, COALESCE(e.title, '') as business_title from sys_notifications n left join sys_user u1 on n.from_user_id = u1.id left join sys_notice e on n.business_id = e.id and n.business_type = 'notice'
and n.business_type = #{notifications.businessType}
and n.business_type IN
#{item}
and n.del_flag = #{notifications.delFlag}
and n.title like concat('%', #{notifications.title}, '%')
and u1.nickname like concat('%', #{notifications.fromNickname}, '%')
order by n.del_flag asc, n.create_time desc
